(function () {
      var workspace = document.querySelector("[data-hr-workspace]");
      if (!workspace) return;
      var filters = Array.prototype.slice.call(workspace.querySelectorAll("[data-hr-filter]"));
      var cards = Array.prototype.slice.call(workspace.querySelectorAll("[data-hr-status]"));
      var caseButtons = Array.prototype.slice.call(workspace.querySelectorAll("button[data-hr-title]"));
      var title = workspace.querySelector("[data-hr-title]:not(button)");
      var status = workspace.querySelector("[data-hr-status-label]:not(button)");
      var body = workspace.querySelector("[data-hr-body]:not(button)");
      var reason = workspace.querySelector("[data-hr-reason]");
      var route = workspace.querySelector("[data-hr-route]");

      filters.forEach(function (filter) {
        filter.addEventListener("click", function () {
          var value = filter.dataset.hrFilter;
          filters.forEach(function (item) { item.classList.remove("is-active"); });
          filter.classList.add("is-active");
          cards.forEach(function (card) {
            var show = value === "all" || card.dataset.hrStatus === value;
            card.hidden = !show;
          });
        });
      });

      caseButtons.forEach(function (button) {
        button.addEventListener("click", function () {
          title.textContent = button.dataset.hrTitle || "";
          status.textContent = button.dataset.hrStatusLabel || "";
          body.textContent = button.dataset.hrBody || "";
          reason.textContent = button.dataset.hrReason || "";
          route.textContent = button.dataset.hrRoute || "";
        });
      });
    }());
